const query = $input.first().json.query || {};

// all=1 -> full alphabetical list for the admin Patients tab
if (String(query.all || '') === '1') {
  return [{ json: { q: '', normalized: '', all: true, skip: false } }];
}

const q = (query.q || query.name || '').trim();

if (!q || q.length < 1) {
  return [{ json: { skip: true, q: q } }];
}

return [{ json: { q: q, normalized: q.toLowerCase().trim(), skip: false } }];

const items = $input.all();
const q = $('Validate Input').first().json.normalized;
// all=1 (Patients tab): every row, alphabetical; otherwise top 15 matches
const ALL = $('Validate Input').first().json.all === true;
const LIMIT = ALL ? Infinity : 15;

function normalize(s) {
  return String(s || '').toLowerCase().trim();
}

// Score: 0 = starts with, 1 = word starts with, 2 = contains
// One entry per row: a patient with several phones (e.g. both parents) appears once per phone
const matches = [];
for (const item of items) {
  const row = item.json || {};
  const name = row.name || '';
  if (!name) continue;
  const norm = normalize(name);
  let score = -1;
  if (norm.startsWith(q)) score = 0;
  else if (norm.split(/\s+/).some(w => w.startsWith(q))) score = 1;
  else if (norm.includes(q)) score = 2;
  if (score === -1) continue;
  matches.push({
    name: String(name).trim(),
    phone: String(row.phone || '').trim(),
    createdAt: String(row.createdAt || '').trim(),
    row: Number(row.row_number) || 0,
    score: score
  });
}

// Best match first; same name -> newest phone first
matches.sort((a, b) => {
  if (a.score !== b.score) return a.score - b.score;
  const byName = a.name.localeCompare(b.name, 'bg');
  if (byName !== 0) return byName;
  return (b.createdAt.localeCompare(a.createdAt)) || (b.row - a.row);
});

const limited = matches.slice(0, LIMIT).map(m => ({ name: m.name, phone: m.phone, createdAt: m.createdAt }));

return [{
  json: {
    success: true,
    q: $('Validate Input').first().json.q,
    count: limited.length,
    total: matches.length,
    patients: limited
  }
}];
